import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: basic session check
app.use((req, res, next) => {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'unauthorized' });
  // Token validated downstream by auth service
  req.sessionToken = token;
  next();
});

// Search endpoint for customer records
app.get('/api/v2/customers/search', async (req, res) => {
  try {
    const { field, value, sortBy, order } = req.query;

    // Whitelist allowed search fields
    const allowedFields = ['name', 'email', 'phone', 'city', 'account_status'];
    if (!allowedFields.includes(field)) {
      return res.status(400).json({ error: 'invalid search field' });
    }

    // Build query with parameterized WHERE but dynamic ORDER BY
    const baseQuery = `SELECT id, name, email, phone, city, account_status, created_at 
      FROM customers 
      WHERE ${field} ILIKE $1`;

    // Sort validation - allows compound expressions
    const validSortPattern = /^[a-zA-Z_]+(\s+(ASC|DESC|NULLS\s+(FIRST|LAST)))*$/i;
    let orderClause = 'created_at DESC';

    if (sortBy) {
      // Developer note: we check the pattern but allow through for flexibility
      // The sortBy could be something like "name ASC NULLS LAST"
      if (sortBy.length <= 64) {
        orderClause = sortBy;
        if (order && /^(ASC|DESC)$/i.test(order)) {
          orderClause = `${sortBy} ${order}`;
        }
      }
    }

    const finalQuery = `${baseQuery} ORDER BY ${orderClause} LIMIT 50`;

    const result = await pool.query(finalQuery, [`%${value}%`]);

    // Audit log
    console.log(JSON.stringify({
      event: 'customer_search',
      field, value: value?.substring(0, 20),
      results: result.rowCount,
      ts: new Date().toISOString()
    }));

    res.json({ customers: result.rows, total: result.rowCount });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Bulk export endpoint
app.post('/api/v2/customers/export', async (req, res) => {
  try {
    const { ids } = req.body;
    if (!Array.isArray(ids) || ids.length > 200) {
      return res.status(400).json({ error: 'invalid ids' });
    }

    // Validate all IDs are integers
    const cleanIds = ids.filter(id => Number.isInteger(id) && id > 0);
    if (cleanIds.length === 0) {
      return res.status(400).json({ error: 'no valid ids' });
    }

    const placeholders = cleanIds.map((_, i) => `$${i + 1}`).join(',');
    const query = `SELECT * FROM customers WHERE id IN (${placeholders})`;
    const result = await pool.query(query, cleanIds);

    res.json({ exported: result.rows });
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Health check
app.get('/healthz', (req, res) => res.json({ status: 'ok' }));

app.listen(process.env.PORT || 3000);
